B.aco=new A.n([B.l,"Limite giornaliero ricompense PvP raggiunto (10/24h).",B.k,"L\xedmite diario de recompensas PvP alcanzado (10/24 h).",B.i,"PvP\u306e1\u65e5\u3042\u305f\u308a\u306e\u5831\u916c\u4e0a\u9650\u306b\u9054\u3057\u307e\u3057\u305f\uff0824\u6642\u9593\u306710\u56de\uff09\u3002",B.h,"PvP \uc77c\uc77c \ubcf4\uc0c1 \ud55c\ub3c4\uc5d0 \ub3c4\ub2ec\ud588\uc2b5\ub2c8\ub2e4 (24\uc2dc\uac04\uc5d0 10\ud68c).",B.f,"\u5df2\u8fbe\u5230PvP\u6bcf\u65e5\u5956\u52b1\u4e0a\u9650\uff0824\u5c0f\u65f610\u6b21\uff09\u3002",B.j,"T\xe4gliches PvP-Belohnungslimit erreicht (10/24 Std.)."],t.N)
