B.afP=new A.n([B.l,"Premio lega riscattato!",B.k,"\xa1Premio de liga reclamado!",B.i,"\u30ea\u30fc\u30b0\u5831\u916c\u3092\u53d7\u3051\u53d6\u308a\u307e\u3057\u305f\uff01",B.h,"\ub9ac\uadf8 \ubcf4\uc0c1\uc744 \uc218\ub839\ud588\uc2b5\ub2c8\ub2e4!",B.f,"\u5df2\u9886\u53d6\u8054\u8d5b\u5956\u52b1\uff01",B.j,"Liga-Belohnung abgeholt!"],t.N)
