B.ady=new A.n([B.l,"RARIT\xc0 SKILL PER STAGE",B.k,"RAREZA DE HABILIDAD POR ETAPA",B.i,"\u30b9\u30c6\u30fc\u30b8\u5225\u30b9\u30ad\u30eb\u30ec\u30a2\u5ea6",B.h,"\uc2a4\ud14c\uc774\uc9c0\ubcc4 \uc2a4\ud0ac \ud76c\uadc0\ub3c4",B.f,"\u5404\u9636\u6bb5\u6280\u80fd\u7a00\u6709\u5ea6",B.j,"F\xc4HIGKEITSSELTENHEIT JE STUFE"],t.N)
B.adJ=new A.n([B.l,"Nove eroi \xb7 300 Shard o una carica gratis",B.k,"Nueve h\xe9roes \xb7 300 Shards o una carga gratis",B.i,"9\u4eba\u306e\u82f1\u96c4 \xb7 300\u30b7\u30e3\u30fc\u30c9\u307e\u305f\u306f\u7121\u6599\u30c1\u30e3\u30fc\u30b8",B.h,"\uc601\uc6c5 9\uba85 \xb7 \uc0e4\ub4dc 300\uac1c \ub610\ub294 \ubb34\ub8cc \ucda9\uc804",B.f,"\u4e5d\u4f4d\u82f1\u96c4 \xb7 300\u788e\u7247\u6216\u4e00\u6b21\u514d\u8d39\u5145\u80fd",B.j,"Neun Helden \xb7 300 Shards oder eine Gratisladung"],t.N)
