B.acK=new A.n([B.l,"Salvataggio locale \xb7 accedi per attivare il backup cloud",B.k,"Partida local \xb7 inicia sesi\xf3n para activar la copia en la nube",B.i,"\u30ed\u30fc\u30ab\u30eb\u30bb\u30fc\u30d6 \xb7 \u30ed\u30b0\u30a4\u30f3\u3057\u3066\u30af\u30e9\u30a6\u30c9\u30d0\u30c3\u30af\u30a2\u30c3\u30d7\u3092\u6709\u52b9\u5316",B.h,"\ub85c\uceec \uc800\uc7a5 \xb7 \ub85c\uadf8\uc778\ud558\uc5ec \ud074\ub77c\uc6b0\ub4dc \ubc31\uc5c5 \ud65c\uc131\ud654",B.f,"\u672c\u5730\u5b58\u6863 \xb7 \u767b\u5f55\u4ee5\u542f\u7528\u4e91\u7aef\u5907\u4efd",B.j,"Lokaler Spielstand \xb7 anmelden f\xfcr Cloud-Backup"],t.N)
B.ac2=new A.n([B.l,"Controllo salvataggio cloud\u2026",B.k,"Comprobando partida en la nube\u2026",B.i,"\u30af\u30e9\u30a6\u30c9\u30bb\u30fc\u30d6\u3092\u78ba\u8a8d\u4e2d\u2026",B.h,"\ud074\ub77c\uc6b0\ub4dc \uc800\uc7a5 \ud655\uc778 \uc911\u2026",B.f,"\u6b63\u5728\u68c0\u67e5\u4e91\u7aef\u5b58\u6863\u2026",B.j,"Cloud-Spielstand wird gepr\xfcft\u2026"],t.N)
